package fr.descentecanyon.app.data.local.catalog.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * A member of descente-canyon.com (generated by `scripts/app/extract_forum_users.py`). Names typed
 * without an account under a debit report are not members and are not here.
 */
@Entity(
    tableName = "forum_users",
    indices = [Index(value = ["normalizedUsername"])],
)
data class ForumUserEntity(
    /** The account name exactly as the site shows it: "lolo" and "Lolo_" are two members. */
    @PrimaryKey val username: String,
    val normalizedUsername: String,
    val forumUserId: Int? = null,
    val debitReportCount: Int = 0,
    val forumPostCount: Int = 0,
    /** Null when the site counters of the member were never seen. */
    val photoCount: Int? = null,
    val canyonSheetContributionCount: Int? = null,
    val lastDebitReportDate: String? = null,
    val lastDebitReportCanyonId: Int? = null,
    val lastDebitReportCanyonName: String? = null,
    val lastForumPostDate: String? = null,
    val lastForumPostUrl: String? = null,
    val updatedAt: String,
)
